<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import { ArrowLeft, ArrowRight, Eye, EyeOff, LockKeyhole, Mail, ShieldCheck, Sprout, LoaderCircle } from '@lucide/vue';
import { ref } from 'vue';

defineProps({ branding: Object });
const form = useForm({ email: '', password: '', remember: false });
const visible = ref(false);
function submit() {
    form.post('/admin/login', { onSuccess: () => form.reset('password') });
}
</script>

