                <div class="signin-store-logo"><img v-if="branding?.header_logo" :src="branding.header_logo" :alt="branding.company_name" /><span v-else>{{ branding?.company_name || 'Your store' }}</span></div>
                <p class="signin-eyebrow">A LITTLE CLARITY. A LOT OF POSSIBILITY.</p>
                <h1 id="signin-title">Welcome back<span>.</span></h1>
                <p class="signin-description">Your store. Your vision. Everything in one place.</p>
                <form @submit.prevent="submit" novalidate class="signin-form">
