                        <div class="signin-input" :class="{ 'has-error': form.errors.email }"><Mail :size="18" /><input id="admin-email" v-model="form.email" type="email" autocomplete="username" placeholder="you@example.com" required :aria-invalid="!!form.errors.email" :aria-describedby="form.errors.email ? 'admin-email-error' : undefined" /></div>
                        <p v-if="form.errors.email" id="admin-email-error" role="alert" class="signin-error">{{ form.errors.email }}</p>
                    </div>
                    <div class="signin-field">
                        <label for="admin-password">Password</label>
                        <div class="signin-input" :class="{ 'has-error': form.errors.password }"><LockKeyhole :size="18" /><input id="admin-password" v-model="form.password" :type="visible ? 'text' : 'password'" autocomplete="current-password" placeholder="Enter your password" required :aria-invalid="!!form.errors.password" :aria-describedby="form.errors.password ? 'admin-password-error' : undefined" /><button class="signin-reveal" type="button" :aria-label="visible ? 'Hide password' : 'Show password'" :aria-pressed="visible" aria-controls="admin-password" @click="visible = !visible"><component :is="visible ? EyeOff : Eye" :size="18" /></button></div>
